document.querySelectorAll('[data-preview-form]').forEach(f=>f.addEventListener('submit',e=>{e.preventDefault();alert('Private Konzeptvorschau. Es werden keine Daten übermittelt.');}));document.querySelectorAll('.collection-toolbar form').forEach(f=>f.addEventListener('submit',e=>{e.preventDefault();const g=document.querySelector('.product-grid');const cards=[...g.children];const direction=f.elements.sort_by.value==='price-descending'?-1:1;cards.sort((a,b)=>direction*(Number(a.querySelector('.price').textContent.replace(/[^0-9,]/g,'').replace(',','.'))-Number(b.querySelector('.price').textContent.replace(/[^0-9,]/g,'').replace(',','.'))));cards.forEach(c=>g.append(c));}));